// Windowless test for nim_lsp.cpp -- the analysis half of mep's own
// Nim language server (`mep-nim-lsp`). Drives the pure functions
// directly: no process, no JSON-RPC client. CHECK(), never assert(): the
// Release build strips assert(). Generated by tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

#include "nim_lsp.h"

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

std::vector<std::string> L(const std::string &text) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : text) {
        if (c == '\n') {
            out.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    out.push_back(cur);
    return out;
}

void TestCompletion() {
    const auto doc = NimLspAnalyze(L("alpha beta\nal"));
    const auto items = NimLspCompletions(*doc, 1, 2);
    CHECK(items.size() == 1 && items[0].label == "alpha");
    CHECK(items[0].replace_start == 0 && items[0].replace_end == 2);
}

void TestRobustness() {
    // Every query on every prefix of a file must not crash.
    const std::string src = "replace with a realistic Nim file\n";
    for (size_t n = 0; n <= src.size(); n++) {
        const auto lines = L(src.substr(0, n));
        const auto doc = NimLspAnalyze(lines);
        const int last = static_cast<int>(lines.size()) - 1;
        const int col = static_cast<int>(lines.back().size());
        NimLspDiagnostics(*doc);
        NimLspCompletions(*doc, last, col);
        NimLspHover(*doc, last, col);
        NimLspSignatureAt(*doc, last, col);
        NimLspSymbols(*doc);
        NimLspFolds(*doc);
    }
}

}  // namespace

int main() {
    TestCompletion();
    TestRobustness();
    std::printf("nim_lsp_test: %d checks passed\n", g_checks);
    return 0;
}
